import $ from "jquery";
import BookListStore from "./stores/BookListStore";
import { autorun } from "mobx";

$(() => {
	let $root = $("#root");
	if ($root.length === 0) {
		$root = $('<div id="root"></div>').appendTo("body");
	}
	const store = new BookListStore();
	store.load();
	autorun(render);

	function render() {
		$root.empty();
		if (store.error) {
			$root.append(`<p>Error: ${store.error}</p>`);
			return;
		}
		if (store.pending) {
			$root.append("<p>Loading...</p>");
			return;
		}
		const $search = $(
			'<input type="text" placeholder="Search books...">',
		).appendTo($root);
		$search.val(store.searchQuery);
		$search.on("keyup", (e) => {
			store.setSearchQuery((e.target as HTMLInputElement).value);
		});
		const $list = $("<dl>").appendTo($root);
		for (const book of store.books) {
			// NOTE: using html to preserve search highlights
			const $topic = $("<dt>").appendTo($list).html(book.title);
			const $details = $("<dd>").appendTo($list);
			const $dList = $("<dl>").appendTo($details);
			$("<dt>").appendTo($dList).text("Author");
			$("<dd>").appendTo($dList).html(book.author);
			$("<dt>").appendTo($dList).text("Download");
			$("<dd>")
				.appendTo($dList)
				.append($("<a>").attr("href", book.filename).text("Download"));
		}
	}
});
