import fuzzy from "fuzzy";
import { makeAutoObservable } from "mobx";
import DbStore from "./DbStore";

export default class BookListStore {
	private dbStore = new DbStore();
	searchQuery = "";

	constructor() {
		makeAutoObservable(this);
	}
	setSearchQuery(query: string) {
		this.searchQuery = query;
	}
	get pending() {
		return this.dbStore.pending;
	}
	get error() {
		return this.dbStore.error;
	}
	get data() {
		return this.dbStore.data ? this.dbStore.data : null;
	}
	get count() {
		return this.dbStore.count;
	}
	get dbLoaded() {
		return this.dbStore.data !== null;
	}

	get books(): { title: string; filename: string; author: string }[] {
		const { data, searchQuery } = this;
		if (!data) {
			return [];
		}
		if (!searchQuery) {
			return data.map(({ filename, metadata: { title, author } }) => ({
				title: title || "(unknown)",
				filename,
				author: author || "(unknown)",
			}));
		}
		const titles = data.map((book) => book.metadata.title || "");
		const results = fuzzy.filter(searchQuery, titles, {
			pre: "<b>",
			post: "</b>",
		});
		return results.map((result) => {
			const {
				filename,
				metadata: { author },
			} = data[result.index];
			return { title: result.string, filename, author: author || "(unknown)" };
		});
	}
	async load() {
		this.dbStore.load();
	}
}
